const long long INF = 1LL << 60;

using namespace std;



int main() {

    int N, K;

    cin >> N >> K;



    vector<long long> h(N);

    for (int i = 0; i < h.size(); ++i) cin >> h[i];



    sort(h.begin(), h.end());



    long long dp[100010];

    for (int i = 0; i < 100010; ++i) dp[i]= INF;

    for (int i = 0; i < h.size() - (K - 1); ++i) dp[i] = h[i+(K-1)] - h[i];



    long long ans = INF;

    for (int i = 0; i < 100010; ++i) ans = min(ans, dp[i]);



    cout << ans << endl;

    return 0;

}

