#include <cstdio>

#include <cmath>

using namespace std;



int n, m=50000, mi;

double cx, cy, d, mx, p=1.0, x[55], y[55];

double f(double p, double q) {return p*p + q*q;}



int main() {

	int i;

	cin >> n;

	for(i=0; i<n; i++) {

		cin >> x[i] >> y[i];

		cx += x[i]; cy += y[i];

	}

	cx /= n; cy /= n;

	while(m--) {

		mx = f(cx - x[0], cy - y[0]);

		mi = 0;

		for(i=1; i<n; i++) {

			d = f(cx - x[i], cy - y[i]);

			if(d > mx) mx = d, mi = i;

		}

		cx += (x[mi] - cx) * p;

		cy += (y[mi] - cy) * p;

		p *= 0.999;

	}

	printf("%.9f", sqrt(mx));

	return 0;

}

