    pNum=0;

    for(int i=2;i<=n;i++){

        if(IsPrime[i])Prime[++pNum]=i;

        for(int j=1;j<=pNum&&Prime[j]*i<=n;j++){

            IsPrime[Prime[j]*i]=false;

            if(i%Prime[j]==0)break;

        }

    }

    return pNum;

}

