long long int kaidan (int n) {

	if (n == 0) {

		return 1;

	} else {

		if (n >= 3) {

			return kaidan(n-3)+kaidan(n-2)+kaidan(n-1);

		} else if (n > 1) {

			return kaidan(n-2)+kaidan(n-1);

		} else {

			return kaidan(n-1);

		}

	}

}





